    "answer": "Cost & I/O Bound: B+Tree PK/UNIQUE Lookup: O(log_B N) page reads; TRUNCATE: O(1) extent deallocation. Overview: How DDL statements mutate system catalog tables (pg_class, sqlite_master), physical storage allocation, and fast O(1) file truncation vs row-by-row DELETE.",
    "back": "Cost & I/O Bound: B+Tree PK/UNIQUE Lookup: O(log_B N) page reads; TRUNCATE: O(1) extent deallocation. Overview: How DDL statements mutate system catalog tables (pg_class, sqlite_master), physical storage allocation, and fast O(1) file truncation vs row-by-row DELETE.",
