    "prompt": "[1.2] State the core relational, algebraic, or transactional invariant that guarantees correctness in \"CREATE TABLE, ALTER TABLE, DROP, TRUNCATE vs DELETE & Catalogs\".",
    "front": "[1.2] State the core relational, algebraic, or transactional invariant that guarantees correctness in \"CREATE TABLE, ALTER TABLE, DROP, TRUNCATE vs DELETE & Catalogs\".",
    "answer": "How DDL statements mutate system catalog tables (pg_class, sqlite_master), physical storage allocation, and fast O(1) file truncation vs row-by-row DELETE. Core Invariant: Primary keys enforce (UNIQUE ∧ NOT NULL); Foreign keys enforce ∀ child.fk ≠ NULL ⇒ ∃ parent.pk = child.fk; time-ordered keys (BIGSERIAL/UUIDv7) append monotonically to the rightmost B+Tree leaf page. (Cost Bound: B+Tree PK/UNIQUE Lookup: O(log_B N) page reads; TRUNCATE: O(1) extent deallocation)",
    "back": "How DDL statements mutate system catalog tables (pg_class, sqlite_master), physical storage allocation, and fast O(1) file truncation vs row-by-row DELETE. Core Invariant: Primary keys enforce (UNIQUE ∧ NOT NULL); Foreign keys enforce ∀ child.fk ≠ NULL ⇒ ∃ parent.pk = child.fk; time-ordered keys (BIGSERIAL/UUIDv7) append monotonically to the rightmost B+Tree leaf page. (Cost Bound: B+Tree PK/UNIQUE Lookup: O(log_B N) page reads; TRUNCATE: O(1) extent deallocation)",
