    "answer": "Random UUIDv4 primary keys scatter inserts uniformly across all B+Tree leaf pages, dropping page fill-factor to ~50% and causing dirty-page write amplification; monotonic UUIDv7 (48-bit Unix ms prefix) keeps the active working set in L3/Buffer Pool. (CREATE TABLE, ALTER TABLE, DROP, TRUNCATE vs DELETE & Catalogs)",
