    "answer": "Tracing a SQL string from lexical tokenization and AST generation to catalog binding, relational algebra rewrites, cost estimation, and physical execution. Core Invariant: A composite B+Tree index on (A, B, C) defines a lexicographic total order (A, then B, then C): prefixes (A), (A, B), and (A, B, C) are SARGable range intervals, while an equality predicate on A and range predicate on B stops index ordering for C. (Cost Bound: B+Tree Point/Range Scan: O(log_B N + K/B) page I/Os; Hash Index Equality: O(1) bucket read)",
