    "prompt": "[5.2] State the core relational, algebraic, or transactional invariant that guarantees correctness in \"MVCC Architecture: Why Readers Never Block Writers and Writers Never Block Readers\".",
    "front": "[5.2] State the core relational, algebraic, or transactional invariant that guarantees correctness in \"MVCC Architecture: Why Readers Never Block Writers and Writers Never Block Readers\".",
    "answer": "Comparing append-version heap MVCC (PostgreSQL) against in-place clustered update + rollback segment undo logs (MySQL InnoDB & Oracle). Core Invariant: Under Snapshot Isolation (MVCC), readers never block writers and writers never block readers; a tuple version V is visible to snapshot S iff V.xmin is committed before S and V.xmax is either invalid or uncommitted/after S. (Cost Bound: MVCC Visibility Check: O(1) xmin/xmax vs Snapshot [xmin, xmax, xip[]); SSI Conflict Tracking: O(active_txns))",
    "back": "Comparing append-version heap MVCC (PostgreSQL) against in-place clustered update + rollback segment undo logs (MySQL InnoDB & Oracle). Core Invariant: Under Snapshot Isolation (MVCC), readers never block writers and writers never block readers; a tuple version V is visible to snapshot S iff V.xmin is committed before S and V.xmax is either invalid or uncommitted/after S. (Cost Bound: MVCC Visibility Check: O(1) xmin/xmax vs Snapshot [xmin, xmax, xip[]); SSI Conflict Tracking: O(active_txns))",
