    "answer": "Dissecting how unvacuumed 32-bit transaction IDs approach the 2-billion horizon, forcing PostgreSQL into emergency read-only shutdown to prevent data loss. Core Invariant: Under Snapshot Isolation (MVCC), readers never block writers and writers never block readers; a tuple version V is visible to snapshot S iff V.xmin is committed before S and V.xmax is either invalid or uncommitted/after S. (Cost Bound: MVCC Visibility Check: O(1) xmin/xmax vs Snapshot [xmin, xmax, xip[]); SSI Conflict Tracking: O(active_txns))",
